#include <src/game/characters/Character.h>
#include <src/game/vehicles/Vehicle.h>
#include <src/game/combat/Weapon.h>
#include <src/game/combat/Rocket.h>
#include <src/game/characters/Transformation.h>
#include <src/game/core/Physics.h>
#define OFF(T, F) __builtin_offsetof(T, F)
unsigned int layout_values[] = {
sizeof(LevelObject), sizeof(Character), sizeof(Vehicle), sizeof(Weapon), sizeof(Rocket), sizeof(Transformation),
OFF(LevelObject, unknown49),
#ifdef WCH_AGGREGATE_FILTER
OFF(Character, collisionFilter) + OFF(b2FilterData, categoryBits),
OFF(Character, collisionFilter) + OFF(b2FilterData, maskBits),
OFF(Character, collisionFilter) + OFF(b2FilterData, groupIndex),
#else
OFF(Character, collisionCategory), OFF(Character, collisionMask), OFF(Character, collisionGroup),
#endif
OFF(Character, facing), OFF(Character, collisionBody), OFF(Character, vehicle),
OFF(Vehicle, unknown56), OFF(Vehicle, driver), OFF(Weapon, weaponType), OFF(Rocket, body), OFF(Transformation, position),
sizeof(b2FilterData), __alignof__(b2FilterData)
};
